create function public.preview_import(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare s uuid:=private.school();c public.classes;j public.import_jobs;r jsonb;existing uuid;st text;nam text;begin perform private.require_access(s,true);if private.role()not in('teacher','administrator')then raise exception 'FORBIDDEN' using errcode='42501';end if;select * into c from public.classes where id=(p->>'classId')::uuid and school_id=s;if not private.assigned(c.id)then raise exception 'FORBIDDEN' using errcode='42501';end if;insert into public.import_jobs(school_id,actor_id,checksum,idempotency_key)values(s,auth.uid(),p->>'checksum',p->>'idempotencyKey')on conflict(school_id,actor_id,idempotency_key)do nothing;select * into j from public.import_jobs where school_id=s and actor_id=auth.uid()and idempotency_key=p->>'idempotencyKey';if j.checksum<>p->>'checksum'then raise exception 'IDEMPOTENCY_CONFLICT';end if;
for r in select value from jsonb_array_elements(p->'rows')loop st:='new';existing:=null;nam:=null;if r->>'error'is not null then st:='invalid';elsif r->>'className'<>c.name or r->>'section'<>c.section then st:='invalid';else select e.student_id,m.display_name into existing,nam from public.enrollments e join public.memberships m on m.id=e.student_id where e.class_id=c.id and e.roll=r->>'roll';if existing is not null then st:=case when lower(trim(nam))=lower(trim(r->>'name'))then 'existing'else 'conflict'end;end if;end if;insert into public.import_rows values(s,j.id,(r->>'row')::int,c.id||':'||(r->>'roll'),st,existing,case when st='invalid'then coalesce(r->>'error','CLASS_MISMATCH')when st='conflict'then 'NAME_ROLL_CONFLICT'else null end,r||jsonb_build_object('classId',c.id))on conflict do nothing;end loop;perform private.audit(s,'import.preview',j.id);return jsonb_build_object('id',j.id,'rows',(select jsonb_agg(jsonb_build_object('row',row_number,'state',state,'studentId',student_id,'error',error_code,'preview',preview))from public.import_rows where job_id=j.id));end$$;
create function public.import_selection(p jsonb)returns jsonb language plpgsql security definer set search_path='' as $$declare j public.import_jobs;begin select * into j from public.import_jobs where id=(p->>'jobId')::uuid;perform private.require_access(j.school_id,true);if j.actor_id<>auth.uid()and private.role()<>'administrator'then raise exception 'FORBIDDEN' using errcode='42501';end if;return coalesce((select jsonb_agg(jsonb_build_object('row',row_number,'identityKey',identity_key,'preview',preview,'state',state,'studentId',student_id))from public.import_rows where job_id=j.id and state in('new','existing','reserved','auth_created','failed')and row_number in(select value::int from jsonb_array_elements_text(p->'rows'))),'[]');end$$;
create function public.import_row_outcome(p jsonb)returns void language plpgsql security definer set search_path='' as $$declare j public.import_jobs;begin select * into j from public.import_jobs where id=(p->>'jobId')::uuid;if j.school_id<>private.school()or j.actor_id<>auth.uid()then raise exception 'FORBIDDEN' using errcode='42501';end if;update public.import_rows set state=p->>'state',student_id=(p->>'studentId')::uuid,error_code=p->>'errorCode'where job_id=j.id and row_number=(p->>'row')::int;perform private.audit(j.school_id,'import.row',j.id,null,jsonb_build_object('row',(p->>'row')::int,'state',p->>'state'));end$$;
revoke execute on function public.preview_import(jsonb),public.import_selection(jsonb),public.import_row_outcome(jsonb)from public,anon,authenticated;grant execute on function public.preview_import(jsonb),public.import_selection(jsonb),public.import_row_outcome(jsonb)to authenticated;
